async function retry<T>(task: () => Promise<T>, attempts: number, base: number): Promise<T> {
  let lastError: unknown;
  for (let n = 0; n < attempts; n++) {
    try {
      return await task();
    } catch (err) {
      lastError = err;
      await new Promise((resolve) => setTimeout(resolve, base * 2 ** n));
    }
  }
  throw lastError;
}

