async function withBackoff<R>(action: () => Promise<R>, maxTries: number, delay: number): Promise<R> {
  let failure: unknown;
  for (let attempt = 0; attempt < maxTries; attempt++) {
    try {
      return await action();
    } catch (e) {
      failure = e;
      await new Promise((done) => setTimeout(done, delay * 2 ** attempt));
    }
  }
  throw failure;
}

